import React, { Component } from "react";
import "./Header.css";
import MenuJson from '../MenuJson';

export default class Header extends Component {
  constructor(props) {
    super(props);
    this.state = {
    header: null,
    };
}

componentDidMount() {
    const pageName = "Header";
    fetch(`http://localhost:3001/${pageName}`) 
        .then(response => response.json())
        .then(page => {
            this.setState({ header : page });
        })
        .catch(error => console.error('Error fetching data:', error));
}

render() {
    const { header } = this.state;
    if (!header) return <div>PAGE NOT FOUND</div>;
    const contentHeader = header.text;
    const page1=MenuJson.find(item => item.MenuName === "Header");

    return (
      <div>
        <nav>
          <ul>
            <li><h1 className="logo" ><a herf="/Homepage" >{MenuJson[8].text}</a></h1></li>
            <li><div className="AboutUs"><a href={MenuJson[9].url}>{MenuJson[9].text}</a></div></li>
          </ul>

          <ul>
            {MenuJson.filter(menuItem => menuItem.menuId === 1).map(headerMenu => (
              <li>
                <a className={headerMenu.style} href={headerMenu.url}>{headerMenu.text}</a>
              </li>
            ))}
          </ul>
        </nav>

        <div className="orange-navbar">
          <div className="navcontainer">
            {MenuJson.filter(menuItem => menuItem.menuId === 2).map(headerMenu => (
              <li>
                <a className={headerMenu.style} href={headerMenu.url}>{headerMenu.text}</a>
              </li>
            ))}
          </div>
        </div>
      </div>
    );
  }
}
